using HakutaiKagami.Core.Contracts;
using Xunit;
namespace HakutaiKagami.Tests;
public sealed class MilitarySuccessionTests
{
    static readonly EntityId Home=new("site:kofu"),Owner=new("org:takeda"),Old=new("person:shingen"),Heir=HistoricalHouseholdCatalog.Edition.People.Single().Id;
    static WorldSession Start(bool retired=false)=>new(NewGameWorld.Create(NewGameWorld.Scenario(HistoricalStartCatalog.Current),[],retired?Old.Value:Heir.Value,42,historicalCatalog:HistoricalStartCatalog.Current,inspectionPolicy:LocalInspectionFindings.Policy,workPolicy:WorkFollowup.Policy,worldArmyPolicy:NpcArmies.CompactCombatPolicy,economyPolicy:HouseSuccession.Policy));
    static void Good(CommandResult r)=>Assert.True(r.Code==ResultCode.Accepted,r.VisibleReason);
    static void At(WorldSession s,long t){while(s.Seconds<t){var n=s.Seconds;s.SetPaused(false);s.AdvanceTo(t,100000);Assert.True(s.Seconds>n);}}
    static void Open(WorldSession s){foreach(var m in s.GetActorView(s.PlayerControl).Messages.Where(m=>m.KnownBody==null).ToArray())Good(s.Open(s.PlayerControl,m.Id,s.Revision));}
    static NewMilitaryInput Input(WorldSession s,NewMilitaryAction a)=>new(new("request:military-succession/"+s.Revision+"/"+a),a);
    static void Send(WorldSession s,NewMilitaryAction a,long amount=0)=>Good(s.DecideNewMilitary(Input(s,a) with{Amount=amount},s.PlayerControl,s.Revision));
    static NewMilitaryInput Request(WorldSession s,bool handover=false)=>Input(s,NewMilitaryAction.Request) with{LedgerPolicy=NewGameMilitary.LedgerIdentityContract,AuthorityPolicy=NewGameMilitary.AuthorityContract,ObservationPolicy=NewGameMilitary.ObservationContract,CycleContract=s.DiagnosticSnapshot().NewMilitary!=null?NewGameMilitary.RenewalContract:null,IssuerPolicy=handover?NewGameMilitary.IssuerSuccessionContract:null};
    static void Succeed(WorldSession s){var id=new EntityId("request:military-head/"+s.Revision);Good(s.ManageHouseSuccession(new(id,HouseSuccessionAction.Nominate,Owner,Heir),s.PlayerControl,s.Revision));Good(s.ManageHouseSuccession(new(new("request:military-head-confirm/"+s.Revision),HouseSuccessionAction.Confirm,Owner,Original:id),s.PlayerControl,s.Revision));At(s,s.Seconds+1);}
    static WorldSession Closed(bool open=true,bool retired=false){var s=Start(retired);Good(s.DecideNewMilitary(Request(s),s.PlayerControl,s.Revision));At(s,s.Seconds+2);Open(s);At(s,s.Seconds+NewGameMilitary.OfferSeconds+3);if(open)Open(s);return s;}
    static WorldSession Changed(){var s=Closed();Succeed(s);return s;}
    static WorldSession Assumed(){var s=Changed();Good(s.DecideNewMilitary(Request(s,true),s.PlayerControl,s.Revision));return s;}
    static void Permit(WorldSession s){At(s,s.Seconds+2);Open(s);Send(s,NewMilitaryAction.Accept);At(s,s.Seconds+2);Open(s);Send(s,NewMilitaryAction.Pickup);}
    static void Rice(WorldSession s,long kg)=>Good(s.ManageMilitaryRice(new(new("request:succession-rice/"+s.Revision),NewGameMilitary.DepotFor(s.DiagnosticSnapshot()),kg),s.PlayerControl,s.Revision));
    static void Finish(WorldSession s){Send(s,NewMilitaryAction.Report);At(s,s.Seconds+2);Send(s,NewMilitaryAction.Return);At(s,s.Seconds+2);Open(s);}
    [Fact]public void OfficeChangeDoesNotChangeOldCaseIssuer(){var s=Changed();var w=s.DiagnosticSnapshot();Assert.Equal(Old,w.NewMilitary!.Terms.Principal);Assert.Equal(Old,NewGameMilitary.CasePrincipal(w));Assert.True(NewGameMilitary.CanAssumeReturnedGarrison(w));Assert.False(NewGameMilitary.View(w).CanPickup);}
    [Fact]public void ExplicitRequestChangesOnlyNewCaseIssuerAndPreservesOriginals(){var s=Changed();var a=s.DiagnosticSnapshot();Good(s.DecideNewMilitary(Request(s,true),s.PlayerControl,s.Revision));var b=s.DiagnosticSnapshot();Assert.Equal(a.NewMilitary!.Terms,b.NewMilitary!.Terms);Assert.Equal(Heir,NewGameMilitary.CasePrincipal(b));Assert.Equal(Old,NewGameMilitary.CasePrincipal(b,a.ElapsedSeconds,a.CommitSequence));Assert.All(a.Messaging.Messages,m=>Assert.Contains(m,b.Messaging.Messages));Assert.All(a.NewMilitary.Authority!.Proofs,p=>Assert.Contains(p,b.NewMilitary.Authority!.Proofs));Assert.Equal(ContractJson.Write(a.ServiceBonds),ContractJson.Write(b.ServiceBonds));Assert.Equal(ContractJson.Write(a.ResourceLots),ContractJson.Write(b.ResourceLots));Assert.Equal(a.Units.Select(u=>u.Id),b.Units.Select(u=>u.Id));Assert.Empty(b.OtherMilitaryLedgers??[]);new WorldSession(ContractJson.Copy(b));}
    [Fact]public void SuccessorPermissionUsesActualNewOfficeAndOldProofsStayOld(){var s=Assumed();Permit(s);var w=s.DiagnosticSnapshot();Assert.Equal(Old,w.NewMilitary!.Authority!.Proofs[0].Source.Issuer);Assert.Equal(Heir,w.NewMilitary.Authority.Proofs.Last().Source.Issuer);Assert.Contains(w.Offices,o=>o.Id==w.NewMilitary.Authority.Proofs.Last().Source.Office&&o.Subject==Heir);Assert.Equal(100,w.Units.Sum(u=>u.Soldiers));new WorldSession(ContractJson.Copy(w));}
    [Fact]public void MissingExplicitHandoverCannotRenewUnderChangedHead(){var s=Changed();Assert.Equal(ResultCode.NotAvailable,s.DecideNewMilitary(Request(s),Heir,s.Revision).Code);}
    [Fact]public void IncumbentCannotUseSuccessionPolicyBeforeSuccession(){var s=Closed();Assert.Equal(ResultCode.NotAvailable,s.DecideNewMilitary(Request(s,true),Heir,s.Revision).Code);}
    [Fact]public void StillOpenOldOfferCannotBeTakenOver(){var s=Start();Good(s.DecideNewMilitary(Request(s),s.PlayerControl,s.Revision));At(s,2);Open(s);Succeed(s);Assert.False(NewGameMilitary.CanAssumeReturnedGarrison(s.DiagnosticSnapshot()));Assert.Equal(ResultCode.NotAvailable,s.DecideNewMilitary(Request(s,true),Heir,s.Revision).Code);}
    [Fact]public void UnknownExpirationDoesNotPermitHandover(){var s=Closed(false);Succeed(s);Assert.False(NewGameMilitary.CanAssumeReturnedGarrison(s.DiagnosticSnapshot()));Open(s);Assert.True(NewGameMilitary.CanAssumeReturnedGarrison(s.DiagnosticSnapshot()));}
    [Fact]public void RepeatAndConflictCannotCreateSecondCase(){var s=Changed();var input=Request(s,true);Good(s.DecideNewMilitary(input,s.PlayerControl,s.Revision));Assert.Equal(ResultCode.AlreadyAccepted,s.DecideNewMilitary(input,Heir,s.Revision).Code);Assert.Equal(ResultCode.IdPayloadConflict,s.DecideNewMilitary(input with{IssuerPolicy="bad"},s.PlayerControl,s.Revision).Code);Assert.Equal(2,NewGameMilitary.Cases(s.DiagnosticSnapshot()).Length);}
    [Theory][InlineData(0)][InlineData(1)][InlineData(2)][InlineData(3)]public void WrongHandoverContractCannotCommit(int part){var s=Changed();var i=Request(s,true);i=part switch{0=>i with{AuthorityPolicy=null},1=>i with{CycleContract=null},2=>i with{IssuerPolicy="unknown"},_=>i with{Action=NewMilitaryAction.Inquire}};var b=ContractJson.Write(s.DiagnosticSnapshot());Assert.Equal(ResultCode.NotAvailable,s.DecideNewMilitary(i,Heir,s.Revision).Code);Assert.Equal(b,ContractJson.Write(s.DiagnosticSnapshot()));}
    [Fact]public void StaleAndWrongActorDoNotCommit(){var s=Changed();var i=Request(s,true);Assert.Equal(ResultCode.StateChanged,s.DecideNewMilitary(i,Heir,s.Revision-1).Code);Assert.Equal(ResultCode.NotAvailable,s.DecideNewMilitary(i,Old,s.Revision).Code);}
    [Fact]public void NewCaseHasNoOldPickupPermission(){var s=Assumed();Assert.Equal(ResultCode.NotAvailable,s.DecideNewMilitary(Input(s,NewMilitaryAction.Pickup),Heir,s.Revision).Code);Assert.False(NewGameMilitary.View(s.DiagnosticSnapshot()).Custody);}
    [Fact]public void RealDepotFoodAndAnotherLoanUseSameLifetimeLedger(){var s=Assumed();Permit(s);Rice(s,10);Send(s,NewMilitaryAction.Load,10*MilitaryEconomy.PersonSecondsPerKg);Send(s,NewMilitaryAction.Deploy);At(s,s.Seconds+10);Send(s,NewMilitaryAction.Enter);Send(s,NewMilitaryAction.Unload,NewGameMilitary.View(s.DiagnosticSnapshot()).Carry);Finish(s);var a=s.DiagnosticSnapshot();Good(s.DecideNewMilitary(Request(s),s.PlayerControl,s.Revision));Permit(s);var b=s.DiagnosticSnapshot();Assert.Equal(ContractJson.Write(a.NewMilitary!.Binding),ContractJson.Write(b.NewMilitary!.Binding));Assert.Equal(a.NewMilitary.Moves,b.NewMilitary.Moves);Assert.Equal(a.NewMilitary.Uses,b.NewMilitary.Uses);Assert.Equal(10*MilitaryEconomy.PersonSecondsPerKg-1000,s.MilitaryEconomyView()!.DepotPersonSeconds);Assert.Equal(3,NewGameMilitary.Cases(b).Length);Assert.Equal(100,b.Units.Sum(u=>u.Soldiers));Assert.Equal(Heir,NewGameMilitary.CasePrincipal(b));new WorldSession(ContractJson.Copy(b));}
    [Theory][InlineData(0)][InlineData(1)]public void ForgedOriginalOrHandoverInputFailsLoad(int kind){var s=Assumed();var w=s.DiagnosticSnapshot();var n=w.NewMilitary!;if(kind==0)w.NewMilitary=n with{Terms=n.Terms with{Principal=Heir}};else{int k=Array.FindLastIndex(n.Requests,q=>q.Input.Action==NewMilitaryAction.Request);n.Requests[k]=n.Requests[k] with{Input=n.Requests[k].Input with{IssuerPolicy=null}};}Assert.Throws<InvalidDataException>(()=>new WorldSession(w));}
    [Theory][InlineData(0)][InlineData(1)][InlineData(2)][InlineData(3)][InlineData(4)][InlineData(5)]public void ActualGenerationRecoveryAndFutureRetainCaseIssuerAndPhysicalStock(int phase){var s=Closed();if(phase>=1)Succeed(s);if(phase>=2)Good(s.DecideNewMilitary(Request(s,true),s.PlayerControl,s.Revision));if(phase>=3)Permit(s);if(phase>=4){Rice(s,10);Send(s,NewMilitaryAction.Load,10*MilitaryEconomy.PersonSecondsPerKg);Send(s,NewMilitaryAction.Deploy);At(s,s.Seconds+3);}if(phase>=5){Send(s,NewMilitaryAction.Enter);Send(s,NewMilitaryAction.Unload,NewGameMilitary.View(s.DiagnosticSnapshot()).Carry);Finish(s);}s.SetPaused(true);var w=s.DiagnosticSnapshot();var store=new GenerationSaveStore(Path.Combine(Path.GetTempPath(),"military-succession-"+Guid.NewGuid().ToString("N")),w.Definitions);Assert.True(store.Save(s,"military",w.WorldId).Published);var host=new WorldSessionHost(Start());Assert.Equal(ResultCode.Accepted,host.CommitLoad(store.Prepare("military"),host.Current,host.Current.Revision));var c=host.Current;Assert.Equal(ContractJson.Write(w),ContractJson.Write(c.DiagnosticSnapshot()));Assert.Equal(ContractJson.Write(NewGameMilitary.ViewWithAuthority(w)),ContractJson.Write(NewGameMilitary.ViewWithAuthority(c.DiagnosticSnapshot())));var dir=Environment.GetEnvironmentVariable("HAKUTAI_WORLD_CLASH_QA_DIR");if(!string.IsNullOrEmpty(dir)){File.WriteAllBytes(Path.Combine(dir,"military-succession-"+phase+".before.json"),ContractJson.Write(w));File.WriteAllBytes(Path.Combine(dir,"military-succession-"+phase+".restored.json"),ContractJson.Write(c.DiagnosticSnapshot()));}foreach(var x in new[]{s,c})At(x,x.Seconds+10);Assert.Equal(ContractJson.Write(s.DiagnosticSnapshot()),ContractJson.Write(c.DiagnosticSnapshot()));}

    static WorldSession UsedOld(){var s=Start();Good(s.DecideNewMilitary(Request(s),s.PlayerControl,s.Revision));Permit(s);Rice(s,10);Send(s,NewMilitaryAction.Load,10*MilitaryEconomy.PersonSecondsPerKg);Send(s,NewMilitaryAction.Deploy);At(s,s.Seconds+5);Send(s,NewMilitaryAction.Enter);Send(s,NewMilitaryAction.Unload,NewGameMilitary.View(s.DiagnosticSnapshot()).Carry);Finish(s);return s;}
    [Fact]public void PhysicalOldLoanFoodAndReportsSurviveChangedIssuer(){var s=UsedOld();var a=s.DiagnosticSnapshot();Succeed(s);Good(s.DecideNewMilitary(Request(s,true),s.PlayerControl,s.Revision));Permit(s);var b=s.DiagnosticSnapshot();Assert.Equal(a.NewMilitary!.Moves,b.NewMilitary!.Moves);Assert.Equal(a.NewMilitary.Uses,b.NewMilitary.Uses);Assert.Equal(a.NewMilitary.Reports,b.NewMilitary.Reports);Assert.Equal(ContractJson.Write(a.MilitaryEconomy),ContractJson.Write(b.MilitaryEconomy));Assert.Equal(a.ResourceLots.Sum(x=>x.Quantity),b.ResourceLots.Sum(x=>x.Quantity));Assert.Equal(a.Units.Select(x=>x.Soldiers),b.Units.Select(x=>x.Soldiers));Assert.Equal(Old,NewGameMilitary.Debriefs(b).Single().Principal);Assert.All(a.Messaging.Messages,m=>Assert.Contains(m,b.Messaging.Messages));new WorldSession(ContractJson.Copy(b));}
    [Fact]public void SecondHandoverCannotRegrantActiveArmy(){var s=Assumed();Permit(s);Assert.False(NewGameMilitary.CanAssumeReturnedGarrison(s.DiagnosticSnapshot()));Assert.Equal(ResultCode.NotAvailable,s.DecideNewMilitary(Request(s,true),Heir,s.Revision).Code);Assert.Equal(100,s.DiagnosticSnapshot().Units.Sum(u=>u.Soldiers));}
    [Fact]public void ActiveCustodyPreventsHeadChangeRatherThanMovingArmy(){var s=Start();Good(s.DecideNewMilitary(Request(s),s.PlayerControl,s.Revision));Permit(s);var id=new EntityId("request:busy-head");var r=s.ManageHouseSuccession(new(id,HouseSuccessionAction.Nominate,Owner,Heir),Heir,s.Revision);if(r.Code==ResultCode.Accepted)Assert.Equal(ResultCode.NotAvailable,s.ManageHouseSuccession(new(new("request:busy-head-confirm"),HouseSuccessionAction.Confirm,Owner,Original:id),Heir,s.Revision).Code);Assert.Equal(Old,HouseSuccession.Head(s.DiagnosticSnapshot(),Owner));Assert.Equal(Old,NewGameMilitary.CasePrincipal(s.DiagnosticSnapshot()));Assert.True(NewGameMilitary.CustodyAt(s.DiagnosticSnapshot(),s.Seconds,s.Revision));}
    [Fact]public void SuccessorAwayFromGarrisonCannotTakeOver(){var s=Changed();Good(s.Submit(TravelWorld.Move(s.DiagnosticSnapshot(),"request:away-successor","castle"),s.Revision));At(s,s.Seconds+2);At(s,s.DiagnosticSnapshot().Branches!.Journeys.Last(j=>j.Actor==Heir).Legs[^1].EndAt+1);Assert.False(NewGameMilitary.CanAssumeReturnedGarrison(s.DiagnosticSnapshot()));Assert.Equal(ResultCode.NotAvailable,s.DecideNewMilitary(Request(s,true),Heir,s.Revision).Code);}
    [Fact]public void OldInquiriesAndNewNoticesRetainActualCaseSenders(){var s=UsedOld();Send(s,NewMilitaryAction.Inquire);At(s,s.Seconds+2);Open(s);var a=s.DiagnosticSnapshot();Succeed(s);Good(s.DecideNewMilitary(Request(s,true),s.PlayerControl,s.Revision));Permit(s);var w=s.DiagnosticSnapshot();Assert.All(a.Messaging.Messages,m=>Assert.Contains(m,w.Messaging.Messages));var root=NewGameMilitary.Cases(w).Last().Id.Value;Assert.All(w.Messaging.Messages.Where(m=>m.Kind=="new-military-notice"&&m.CorrelationId==root),m=>Assert.Equal(Heir.Value,m.SenderId));Assert.All(w.Messaging.Messages.Where(m=>m.Kind=="new-military-notice"&&m.CorrelationId!=root),m=>Assert.Equal(Old.Value,m.SenderId));new WorldSession(ContractJson.Copy(w));}
    [Fact]public void PreviousPermissionCannotAuthorizeChangedCaseWithoutOpeningNewPermission(){var s=Assumed();At(s,s.Seconds+2);Open(s);Send(s,NewMilitaryAction.Accept);At(s,s.Seconds+2);Assert.False(NewGameMilitary.View(s.DiagnosticSnapshot()).CanPickup);Assert.Equal(ResultCode.NotAvailable,s.DecideNewMilitary(Input(s,NewMilitaryAction.Pickup),Heir,s.Revision).Code);Open(s);Send(s,NewMilitaryAction.Pickup);new WorldSession(s.DiagnosticSnapshot());}

    static WorldSession Retired(){var s=Closed(retired:true);Succeed(s);return s;}
    [Fact]public void RetiredHeadRequestsFreshMilitaryWithoutBecomingSuccessorsPersonalVassal(){var s=Retired();var a=s.DiagnosticSnapshot();Assert.True(NewGameMilitary.CanAssumeReturnedGarrison(a));Good(s.DecideNewMilitary(Request(s,true),Old,s.Revision));Permit(s);var w=s.DiagnosticSnapshot();Assert.Equal(Old,w.NewMilitary!.Terms.Principal);Assert.Equal(Heir,NewGameMilitary.CasePrincipal(w));Assert.Equal(ContractJson.Write(a.ServiceBonds),ContractJson.Write(w.ServiceBonds));Assert.DoesNotContain(w.ServiceBonds,b=>b.Subject==Old&&b.Target==Heir);var proof=w.NewMilitary.Authority!.Proofs.Last();Assert.Equal(NewGameMilitaryAuthority.HouseholdMilitaryAgreementContract,proof.Source.Contract);Assert.Equal(Heir,proof.Source.Issuer);Assert.Equal(Old,proof.Source.Agent);Assert.Null(proof.Source.Service);new WorldSession(ContractJson.Copy(w));}
    [Fact]public void RetiredHeadStillNeedsNewOfferAcceptanceAndOpening(){var s=Retired();Good(s.DecideNewMilitary(Request(s,true),Old,s.Revision));Assert.Equal(ResultCode.NotAvailable,s.DecideNewMilitary(Input(s,NewMilitaryAction.Pickup),Old,s.Revision).Code);At(s,s.Seconds+2);Open(s);Send(s,NewMilitaryAction.Accept);At(s,s.Seconds+2);Assert.Equal(ResultCode.NotAvailable,s.DecideNewMilitary(Input(s,NewMilitaryAction.Pickup),Old,s.Revision).Code);Open(s);Send(s,NewMilitaryAction.Pickup);Assert.True(NewGameMilitary.View(s.DiagnosticSnapshot()).Custody);}
    [Fact]public void RetiredCommanderCanReturnThenReceiveAnotherSeparateMilitaryPermission(){var s=Retired();Good(s.DecideNewMilitary(Request(s,true),Old,s.Revision));Permit(s);Finish(s);Good(s.DecideNewMilitary(Request(s),Old,s.Revision));Permit(s);Assert.Equal(Heir,NewGameMilitary.CasePrincipal(s.DiagnosticSnapshot()));Assert.Equal(3,NewGameMilitary.Cases(s.DiagnosticSnapshot()).Length);Assert.Equal(100,s.DiagnosticSnapshot().Units.Sum(u=>u.Soldiers));new WorldSession(s.DiagnosticSnapshot());}
    [Fact]public void SuccessorMilitaryAgreementDoesNotGrantPoliticalHeadAuthority(){var s=Retired();Good(s.DecideNewMilitary(Request(s,true),Old,s.Revision));Permit(s);var w=s.DiagnosticSnapshot();Assert.Null(FactionStances.ResolveAuthority(w,Old,Owner,w.ElapsedSeconds,w.CommitSequence));Assert.NotNull(FactionStances.ResolveAuthority(w,Heir,Owner,w.ElapsedSeconds,w.CommitSequence));Assert.All(w.NewMilitary!.Authority!.Grants,g=>Assert.Equal(Old,g.Mandate.Agent));}
    [Fact]public void RetiredCommanderCannotUseItsOwnFormerHeadAsNewIssuer(){var s=Retired();Assert.Equal(ResultCode.NotAvailable,s.DecideNewMilitary(Request(s),Old,s.Revision).Code);Assert.Equal(Old,NewGameMilitary.CasePrincipal(s.DiagnosticSnapshot()));}
    [Fact]public void SourceArmyOwnerAndDepotCannotBeChangedByNewIssuerRequest(){var s=Retired();var a=s.DiagnosticSnapshot();Good(s.DecideNewMilitary(Request(s,true),Old,s.Revision));Permit(s);var w=s.DiagnosticSnapshot();Assert.Equal(a.NewMilitary!.Terms,w.NewMilitary!.Terms);Assert.Equal(ContractJson.Write(a.NewMilitary.Binding),ContractJson.Write(w.NewMilitary.Binding));Assert.All(w.Units,u=>Assert.Equal(Owner,u.Organization));Assert.Equal(a.ResourceLots.Select(l=>l.Id),w.ResourceLots.Select(l=>l.Id));}
    [Theory][InlineData(0)][InlineData(1)][InlineData(2)][InlineData(3)]public void RetiredCommanderActualSaveAndRecoveryKeepSeparateMilitaryAgreement(int phase){var s=Retired();if(phase>=1)Good(s.DecideNewMilitary(Request(s,true),Old,s.Revision));if(phase>=2)Permit(s);if(phase>=3)Finish(s);s.SetPaused(true);var w=s.DiagnosticSnapshot();var store=new GenerationSaveStore(Path.Combine(Path.GetTempPath(),"retired-military-"+Guid.NewGuid().ToString("N")),w.Definitions);Assert.True(store.Save(s,"retired",w.WorldId).Published);var host=new WorldSessionHost(Start(true));Assert.Equal(ResultCode.Accepted,host.CommitLoad(store.Prepare("retired"),host.Current,host.Current.Revision));var c=host.Current;Assert.Equal(ContractJson.Write(w),ContractJson.Write(c.DiagnosticSnapshot()));var dir=Environment.GetEnvironmentVariable("HAKUTAI_WORLD_CLASH_QA_DIR");if(!string.IsNullOrEmpty(dir)){File.WriteAllBytes(Path.Combine(dir,"retired-military-"+phase+".before.json"),ContractJson.Write(w));File.WriteAllBytes(Path.Combine(dir,"retired-military-"+phase+".restored.json"),ContractJson.Write(c.DiagnosticSnapshot()));}foreach(var x in new[]{s,c})At(x,x.Seconds+10);Assert.Equal(ContractJson.Write(s.DiagnosticSnapshot()),ContractJson.Write(c.DiagnosticSnapshot()));}

    [Fact]public void RetiredCommanderUsesActualSuccessorHouseRiceWithoutPrivateIncome(){var s=Retired();Good(s.DecideNewMilitary(Request(s,true),Old,s.Revision));Permit(s);var old=s.DiagnosticSnapshot();Rice(s,10);Send(s,NewMilitaryAction.Load,10*MilitaryEconomy.PersonSecondsPerKg);Send(s,NewMilitaryAction.Deploy);At(s,s.Seconds+7);Send(s,NewMilitaryAction.Enter);Send(s,NewMilitaryAction.Unload,NewGameMilitary.View(s.DiagnosticSnapshot()).Carry);Finish(s);var w=s.DiagnosticSnapshot();Assert.Equal(10*MilitaryEconomy.PersonSecondsPerKg-700,s.MilitaryEconomyView()!.DepotPersonSeconds);Assert.Equal(NewGameWork.Balance(old,Old),NewGameWork.Balance(w,Old));Assert.Equal(Heir,NewGameMilitary.CasePrincipal(w));new WorldSession(ContractJson.Copy(w));}
}
